// Package contracts embeds the read-only export of
// justskiv/currency/contracts: the currency catalog with the peg table, the
// wire schema v1 and the bundled snapshot of the app. The files are
// generated by contracts/tools/export_rates.py in that repository and must
// not be edited here; SHA256SUMS records their hashes and CI compares them.
package contracts

import (
	"bufio"
	"bytes"
	"crypto/sha256"
	_ "embed"
	"encoding/hex"
	"errors"
	"fmt"
	"slices"
	"strings"
)

var (
	//go:embed rates-contract.json
	_contract []byte

	//go:embed rates.schema.json
	_schema []byte

	//go:embed rates-snapshot.json
	_snapshot []byte

	//go:embed SHA256SUMS
	_sums []byte
)

// Contract returns rates-contract.json: catalog codes, multiRate, usdPegs,
// crossPegs and the source revision.
func Contract() []byte { return slices.Clone(_contract) }

// Schema returns rates.schema.json, the wire format v1.
func Schema() []byte { return slices.Clone(_schema) }

// Snapshot returns rates-snapshot.json, the app's bundled snapshot. The job
// uses it only as the jump baseline before its first publication.
func Snapshot() []byte { return slices.Clone(_snapshot) }

// Verify checks the embedded files against SHA256SUMS, so a hand edit of
// an exported file fails CI.
func Verify() error {
	files := map[string][]byte{
		"rates-contract.json": _contract,
		"rates.schema.json":   _schema,
		"rates-snapshot.json": _snapshot,
	}
	listed := make(map[string]bool, len(files))
	var errs []error
	sc := bufio.NewScanner(bytes.NewReader(_sums))
	for sc.Scan() {
		line := sc.Text()
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		sum, name, ok := strings.Cut(line, "  ")
		data, known := files[name]
		if !ok || !known {
			errs = append(errs, fmt.Errorf("SHA256SUMS: unexpected line %q", line))
			continue
		}
		listed[name] = true
		got := sha256.Sum256(data)
		if hex.EncodeToString(got[:]) != sum {
			errs = append(errs, fmt.Errorf("%s does not match SHA256SUMS: edited by hand?", name))
		}
	}
	if err := sc.Err(); err != nil {
		errs = append(errs, err)
	}
	for name := range files {
		if !listed[name] {
			errs = append(errs, fmt.Errorf("SHA256SUMS lacks %s", name))
		}
	}
	return errors.Join(errs...)
}
